pair<ll, vector<int>> mitm(int N) {
    int MD = 1;
    if (N == 1) {
        cout << "1\n1\n";
        return {1, {1}};
    }
    for (; (MD + 1) * (MD + 1) <= N; ++MD);
    vector<vector<vector<int>>> MP(MD + 1, vector<vector<int>>(N + 1));
    vector<int> latest(N + 1, 1), diag;
    auto bf = [&](auto& self, int k) -> void {
        int cur = latest.size() - 1;
        int d = diag.size() + 1;
        if (d > 1) {
            auto& x = MP[d - 1][k];
            x.insert(x.end(), diag.begin(), diag.end());
        }
        if (d * d > N || k + d > N) return;
        vector<int> cp = latest;
        for (int sz = min(N - d - k, cur - 1); sz >= 0; --sz) {
            latest.resize(sz + 1);
            for (int i = sz; i >= 0; --i)
                latest[i] = cp[i + 1] + (i < sz ? latest[i + 1] : 0);
            diag.emplace_back(latest[0]);
            self(self, k + sz);
            diag.pop_back();
        }
        latest = cp;
    };
    bf(bf, 0);
    ll ANS = 0;
    const int* b1 = nullptr;
    const int* b2 = nullptr;
    int bd = 0;
    // clock_t st = clock();
    for (int d = 1; d <= MD; ++d) {
        for (int k = 0; k <= N - d; ++k) {
            if (k > N - d - k) continue;
            const auto& v1s = MP[d][k];
            const auto& v2s = MP[d][N - d - k];
            for (size_t a = 0; a < v1s.size(); a += d) {
                const int* v1 = &v1s[a];
                for (size_t b = 0; b < v2s.size(); b += d) {
                    const int* v2 = &v2s[b];
                    ll res = 0;
                    for (int i = 0; i < d; ++i) res += ll(v1[i]) * v2[i];
                    if (res > ANS) {
                        ANS = res;
                        b1 = v1;
                        b2 = v2;
                        bd = d;
                    }
                }
            }
        }
    }
    auto convert = [&](const int* b) {
        vector<int> res;
        vector<int> last(N + 1, 1);
        for (int d = 0; d < bd; ++d) {
            ll sum = 0;
            int sz = 0;
            for (int i = 1; i < last.size(); ++i) {
                sum += last[i];
                if (sum == b[d]) {
                    sz = i - 1;
                    break;
                }
            }
            res.emplace_back(sz);
            vector<int> nw(sz + 1);
            for (int i = sz; i >= 0; --i)
                nw[i] = last[i + 1] + (i < sz ? nw[i + 1] : 0);
            last = move(nw);
        }
        return res;
    };
    vector<int> bot = convert(b2);
    vector<int> top = convert(b1);
    // for (int d = 0; d < bd; ++d) cout << b1[d] << ' ';
    // cout << endl;
    // for (int d = 0; d < bd; ++d) cout << b2[d] << ' ';
    // cout << endl;
    // cout << bd << endl;
    // for (auto& x : bot) cout << x << ' ';
    // cout << endl;
    // for (auto& x : top) cout << x << ' ';
    // cout << endl;
    vector<int> answ(bot[0] + 1, 1);
    for (int d = 1; d < bd; ++d)
        for (int i = d; i <= d + bot[d]; ++i)
            ++answ[i];
    for (int d = 0; d < bd; ++d)
        answ[d] += top[d];
    // printf(">> mitm time: %.2fms\n", double(clock() - st) / CLOCKS_PER_SEC * 1000);
    return {ANS, answ};
    // cout << ANS << endl;
    // for (auto& x : answ) cout << x << ' ';
    // cout << endl;
}
 
